TransactionImportResults = {
    init: async function(app, container, instance) {
        // extract the packaged data
        var dataPath = "DMS/Data/Transactions/Processed/" + instance.Start.split("T")[0] + "/";
        var app = await api.get("ContentManagement/App(" + app.Id + ")");
        app.Config = JSON.parse(app.ConfigJson);
        await api.get(dataPath +  "Report-" + instance.Id + ".json").then((report) => {
            TransactionImportResults.setupFileList(dataPath, report, $(".container[name=files]", container));
            TransactionImportResults.setupSummary(report, $(".container[name=summary]", container));
            TransactionImportResults.setupTSet(app, report.Invoices, $(".container[name=invoices]", container));
            TransactionImportResults.setupTSet(app, report.Credits, $(".container[name=credits]", container));
            TransactionImportResults.setupTSet(app, report.Payments, $(".container[name=payments]", container));
        }).catch((err) => {
            notification.error(err.responseText);
        });
    },

    setupFileList: function(dataPath, report, container) {
        var files = report.FilesProccessed.map(function(f) { return { name: f, link: api.apiRoot + dataPath + f + "?t=" + session.token }; });
        var links = files.map(f => "<a download='" + f.name + "' href='" + f.link + "'>" + f.name + "</a>");
        $("[name=list]", container).append(links.join("<br>"));
    },

    setupSummary: function(report, container) {
        $("[name=added]", container).append(report.Invoices.Imported + report.Credits.Imported + report.Payments.Imported);
        $("[name=updated]", container).append(report.Invoices.Updated + report.Credits.Updated + report.Payments.Updated);
        $("[name=failures]", container).append(report.Invoices.Failures.length + report.Credits.Failures.length + report.Payments.Failures.length);
        $("[name=total]", container).append(report.Invoices.Total + report.Credits.Total + report.Payments.Total);
    },

    setupTSet: function(app, data, container) {
        container.append($("template[name=transactionStats]").html());
        $("[name=added]", container).append(data.Imported);
        $("[name=updated]", container).append(data.Updated);
        $("[name=failures] > a", container).append(data.Failures.length);
        $("[name=failures] > a", container).on("click", function(e) { TransactionImportResults.openFailureDialog(app, data.Failures); });
        $("[name=total]", container).append(data.Total);
    },

    openFailureDialog: function(app, failures) {
        // transform the source data to extract the key details
        var itemData = failures.map(function(i) { 
            return  {
                clientRef: TransactionImportResults.getClientRef(i.Item, app.Config.B2B.SourceSystem),
                number: i.Item.Number,
                message: i.Message
            };
        });

        // build the dialog
        var dialog = new Dialog({ 
            name: "failedItemList", 
            title: "Failures", 
            width: "1000px", 
            height: "600px",
        });

        dialog.init(() => {
            // build the grid
            var grid = new GridWidget(dialog.element, {data: itemData, pageSize: 20 });
            grid.editable = false;
            grid.groupable = false;
            grid.columns = [
                { field: "clientRef", type: "string", title:"Client Reference", width: 120 },
                { field: "number", type: "string", title:"Number", width: 120 },
                { field: "message", type: "string", title: "Problem" }
            ];
            grid.init();
        });
    },

    getClientRef: function(item, source) {
        if(item && item.References) {
            var clientRef = item.References.filter(r => r.SystemId == source)[0];
            if(clientRef) { return clientRef.Value; } 
            else { return ""; }
        } else {
            return "";
        }
        
    }
}
